## WP5 — Folders for rooms

### 5.1 Folders already store arbitrary conversation keys

`Folder.convs` is `string[]` and `assign_conv` does no validation — `src/lib/server/__tests__/folders.test.ts:67`
already assigns `'g:g1'`. So the storage layer needs no change to hold rooms. What it does need is a
way to keep chat folders and room folders apart, so a folder named "gaming" made on the rooms page
does not appear as a filter pill on the chats page.

### 5.2 Add a kind to `Folder`

`src/lib/server/folders.ts`:

```ts
export interface Folder {
    s: 'fo';
    id: string;
    ow: string;
    k: 'c' | 'r';  // 'c' = chat folder, 'r' = room folder (indexed: 'k')
    name: string;
    convs: string[]; // peer uids for 'c'; room ids for 'r'
    d: number;
}

export async function save_folder(
    env: QEnv,
    owner: string,
    name: string,
    kind: 'c' | 'r' = 'c'
): Promise<Folder> {
    await ensure(env);
    const fo: Folder = { s: 'fo', id: new_id(), ow: owner, k: kind, name, convs: [], d: Date.now() };
    await upsert(env, [{ id: fo.id, vector: ZV, payload: fo as unknown as Record<string, unknown> }]);
    return fo;
}

export async function list_folders(env: QEnv, uid: string, kind?: 'c' | 'r'): Promise<Folder[]> {
    await ensure(env);
    const pts = await scroll(env, f(eq('s', 'fo'), eq('ow', uid)), 200);
    return pts
        .map((p) => p.payload as unknown as Folder)
        // records written before folders had a kind are chat folders
        .filter((fo) => !kind || (fo.k ?? 'c') === kind)
        .sort((a, b) => a.d - b.d);
}
```

**Filter in JS, not in Qdrant, for the kind.** Existing folder records have no `k` field at all, and
`eq('k','c')` would exclude them — silently losing every folder every existing user has made. The
`?? 'c'` default in JS is the migration.

Note: room folders store the **bare room id**, not `g:<id>`. Keep it symmetric with chat folders
storing a bare peer uid. `owned_folder`, `assign_conv`, `unassign_conv`, `delete_folder` need no
changes.

`src/routes/api/folders/+server.ts`:

```ts
export const GET: RequestHandler = async ({ url, locals }) => {
    if (!locals.user) throw error(401, 'auth');
    const k = url.searchParams.get('kind');
    const kind = k === 'r' || k === 'c' ? k : undefined;
    return json({ folders: await list_folders(env, locals.user.id, kind) });
};

export const POST: RequestHandler = async ({ request, locals }) => {
    if (!locals.user) throw error(401, 'auth');
    const b = (await request.json().catch(() => null)) as { name?: string; kind?: string } | null;
    const name = b?.name?.trim();
    if (!name) throw error(400, 'name required');
    const kind = b?.kind === 'r' ? 'r' : 'c';
    return json({ folder: await save_folder(env, locals.user.id, name, kind) });
};
```

### 5.3 Extract the folder bar into a shared component

Both `/app/chats` and `/app/rooms` need the identical pill row + "new folder" input + edit modal.
Write it once.

`src/lib/components/FolderBar.svelte`:

```svelte
<script lang="ts">
    import Modal from './Modal.svelte';
    import { FolderPlus, Pencil, Plus, Minus } from '@lucide/svelte';

    export type Folder = { id: string; name: string; convs: string[] };
    type Item = { id: string; name: string };

    let {
        folders = $bindable([] as Folder[]),
        active = $bindable(null as string | null),
        items = [] as Item[],
        kind = 'c' as 'c' | 'r',
        itemNoun = 'chats'
    } = $props();

    let newName = $state('');
    let editing = $state(false);
    let activeFolder = $derived(folders.find((fo) => fo.id === active) ?? null);
    const inFolder = (id: string) => !!activeFolder?.convs.includes(id);

    async function create() {
        const name = newName.trim();
        if (!name) return;
        newName = '';
        const res = await fetch('/api/folders', {
            method: 'POST',
            headers: { 'content-type': 'application/json' },
            body: JSON.stringify({ name, kind })
        });
        if (res.ok) folders = [...folders, (await res.json()).folder];
    }

    async function toggle(id: string) {
        const folderId = active;
        if (!folderId) return;
        const adding = !inFolder(id);
        const patch = (add: boolean) =>
            (folders = folders.map((fo) =>
                fo.id !== folderId
                    ? fo
                    : { ...fo, convs: add ? [...fo.convs, id] : fo.convs.filter((c) => c !== id) }
            ));
        patch(adding); // optimistic
        const res = adding
            ? await fetch(`/api/folders/${folderId}`, {
                    method: 'POST',
                    headers: { 'content-type': 'application/json' },
                    body: JSON.stringify({ conv: id })
                })
            : await fetch(`/api/folders/${folderId}?conv=${encodeURIComponent(id)}`, { method: 'DELETE' });
        if (!res.ok) patch(!adding); // roll back — never claim a membership the server rejected
    }
</script>
```

The markup is the existing `/app` block, lifted verbatim from
